<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><link rel="icon" type="image/png" href="{{ asset('images/cnet-library-icon.png') }}"><meta name="referrer" content="no-referrer"><meta name="robots" content="noindex,nofollow,noarchive"><title>Digital ID - {{ $student->name }}</title><style>*{box-sizing:border-box}body{font-family:Inter,Arial,sans-serif;background:#eef3f6;margin:0;color:#172033}.wrap{max-width:820px;margin:34px auto;padding:0 18px}.toolbar{display:flex;justify-content:space-between;gap:10px;margin-bottom:16px}.btn{background:#102a43;color:#fff;border:0;border-radius:10px;padding:10px 15px;text-decoration:none;cursor:pointer;font-weight:700}.id{background:#fff;border:1px solid #d9e3ec;border-radius:22px;overflow:hidden;box-shadow:0 18px 50px rgba(15,23,42,.12)}.head{padding:22px 26px;background:linear-gradient(135deg,#102a43,#0f766e);color:#fff;display:flex;justify-content:space-between;gap:20px;align-items:center}.brand{font-size:24px;font-weight:850}.badge{background:rgba(255,255,255,.15);padding:7px 11px;border-radius:999px;font-size:12px;font-weight:800}.body{padding:26px;display:grid;grid-template-columns:1fr 240px;gap:28px}.identity{display:flex;align-items:center;gap:18px;margin-bottom:14px}.student-photo{width:125px;height:150px;object-fit:cover;border-radius:14px;border:2px solid #d9e3ec;background:#f1f5f9;flex:0 0 auto}.photo-placeholder{width:125px;height:150px;border-radius:14px;border:2px dashed #a8bac8;background:#f1f5f9;display:flex;align-items:center;justify-content:center;text-align:center;color:#718096;font-size:13px;font-weight:800;flex:0 0 auto}.name{font-size:31px;font-weight:850;color:#102a43}.code{display:inline-block;margin:6px 0 15px;background:#e8f5f2;color:#0f766e;padding:5px 10px;border-radius:8px;font-weight:800}.details{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}.detail{background:#f7f9fb;border-radius:11px;padding:11px}