hoto" src="{{ asset('storage/'.$student->photo) }}" alt="{{ $student->name }} photo">@else<div class="photo-placeholder">STUDENT<br>PHOTO</div>@endif<div><div class="name">{{ $student->name }}</div><div class="code">{{ $student->student_code }}</div></div></div><div class="details"><div class="detail"><div class="label">Branch</div><div class="value">{{ $student->branch?->name ?? '—' }}</div></div><div class="detail"><div class="label">Mobile</div><div class="value">{{ $student->mobile }}</div></div><div class="detail"><div class="label">Study Slot</div><div class="value">{{ $student->activeMembership?->studySlot?->name ?? '—' }}</div></div><div class="detail"><div class="label">Valid Until</div><div class="value">{{ $student->activeMembership?->expiry_date?->format('d M Y') ?? '—' }}</div></div></div><div class="notice">This QR is for attendance verification. The underlying attendance token is intentionally hidden and should never be shared separately.</div></div><div class="qrbox"><img src="{{ $qrDataUri }}" alt="Student attendance QR code"><strong>Attendance QR</strong><div class="muted" style="font-size:12px;margin-top:5px">Present to authorized library staff only</div></div></div><div class="foot">Valid with an active C-Net Library membership. Do not post screenshots or copies of this card publicly.</div></div></div></body></html>